`,n.jsx(t.p,{children:n.jsx(t.code,{children:"idempotence"})}),`
`]}),`
`,n.jsx(t.p,{children:"appears in only a few hundred documents."}),`
`,n.jsx(t.p,{children:"Finding it is much more informative."}),`
`,n.jsx(t.p,{children:"IDF captures exactly this idea."}),`
`,n.jsx(t.p,{children:"A common form is:"}),`
